begin;select plan(22);
select has_table('public','notification_templates','templates exist');select has_table('public','notification_events','outbox exists');select has_table('public','notification_deliveries','delivery history exists');select has_table('public','notification_preferences','preferences exist');select has_table('public','email_suppressions','suppressions exist');
select col_is_unique('public','notification_events','idempotency_key','event idempotency is unique');select ok((select exists(select 1 from pg_indexes where indexname='notification_template_one_active')),'one active template per locale');
select has_function('public','claim_notification_events',array['integer'],'SKIP LOCKED worker claim exists');select has_function('public','finish_notification_event',array['uuid','boolean','text','text','text','text'],'delivery completion exists');select has_function('public','enqueue_pickup_reminders',array[]::text[],'reminder outbox exists');
select ok(position('skip locked' in lower(pg_get_functiondef('public.claim_notification_events(integer)'::regprocedure)))>0,'workers use skip locked');select ok(position('on conflict(idempotency_key) do nothing' in lower(pg_get_functiondef('public.enqueue_pickup_reminders()'::regprocedure)))>0,'reminders are idempotent');
select is((select count(*)::integer from public.notification_templates where status='active'),19,'initial transactional templates active');select is((select count(*)::integer from public.app_settings where key like 'communications.%'),5,'retry and retention settings exist');
select throws_ok($$update public.notification_templates set subject_template='Mutado' where key='order-confirmed' and status='active'$$,'23514','active_template_immutable','active template immutable');
select throws_ok($$insert into public.notification_templates(key,name,subject_template,body_html_template,body_text_template,status,version)values('unsafe','Unsafe','x','<script>x</script>','x','draft',1)$$,'23514',null,'scripts rejected');
select throws_ok($$insert into public.notification_preferences(customer_id,category,enabled)values(gen_random_uuid(),'transactional',false)$$,'23514',null,'mandatory transactional cannot be disabled');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select throws_ok($$select * from public.claim_notification_events(1)$$,'42501',null,'client cannot claim queue');select throws_ok($$select public.finish_notification_event(gen_random_uuid(),true,'fake',null,null,null)$$,'42501',null,'client cannot finish delivery');select throws_ok($$select public.enqueue_pickup_reminders()$$,'42501',null,'client cannot schedule reminders');
select ok((select relrowsecurity from pg_class where oid='public.notification_events'::regclass),'event RLS');select ok((select relrowsecurity from pg_class where oid='public.email_suppressions'::regclass),'suppression RLS');select * from finish();rollback;
